<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Detail Analisis</title><style>body{font-family:Arial;margin:30px;background:#f5f7fb;color:#172033}.card{background:#fff;padding:20px;border-radius:12px;margin-bottom:18px;box-shadow:0 2px 10px #0001}table{width:100%;border-collapse:collapse}td{padding:8px;border-bottom:1px solid #eee}button,a{padding:8px 12px;border-radius:7px;border:0;background:#173f7a;color:#fff;text-decoration:none}form{display:inline}.danger{background:#a22}</style></head><body><div class="card"><a href="{{route('analysis.index')}}">← Kembali</a></div><div class="card"><h1>Detail {{$analysis->parameter}}</h1><table><tr><td>Sample</td><td>{{$analysis->sample_code}}</td></tr><tr><td>Method</td><td>{{$analysis->method_version}}</td></tr><tr><td>Analis</td><td>{{$analysis->analyst}}</td></tr><tr><td>Tanggal</td><td>{{$analysis->analysed_at}}</td></tr><tr><td>Status</td><td><b>{{$analysis->status}}</b></td></tr></table></div><div class="card"><h3>Input</h3><pre>{{json_encode($analysis->inputs,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE)}}</pre><h3>Calculation</h3><pre>{{json_encode($analysis->calculation,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE)}}</pre>@if($analysis->uncertainty)<h3>Uncertainty</h3><pre>{{json_encode($analysis->uncertainty,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE)}}</pre>@endif</div><div class="card">@if(session('success'))<p>{{session('success')}}</p>@endif @if(in_array(session('lab_user.role'),['analyst','admin']) && in_array($analysis->status,['DRAFT','REVISION_REQUIRED','REJECTED']))<form method="post" action="{{route('analysis.submit',$analysis)}}">@csrf<button>Submit for Review</button></form>@endif @if(in_array(session('lab_user.role'),['analyst','admin']) && $analysis->status!=='APPROVED')<a href="{{route('analysis.edit',$analysis)}}">Edit</a> <form method="post" action="{{route('analysis.delete',$analysis)}}" onsubmit="return confirm('Hapus data?')">@csrf @method('DELETE')<button class="danger">Delete</button></form>@endif @if(in_array(session('lab_user.role'),['supervisor','admin']) && $analysis->status==='READY_FOR_REVIEW')<form method="post" action="{{route('analysis.review',$analysis)}}">@csrf<input type="hidden" name="decision" value="APPROVED"><button>Approve</button></form> <form method="post" action="{{route('analysis.review',$analysis)}}">@csrf<input type="hidden" name="decision" value="REVISION_REQUIRED"><button>Request Revision</button></form> <form method="post" action="{{route('analysis.review',$analysis)}}">@csrf<input type="hidden" name="decision" value="REJECTED"><button class="danger">Reject</button></form>@endif<div class="card"><h3>Audit Trail</h3><table><tr><th>Waktu</th><th>Actor</th><th>Action</th><th>Status</th><th>Catatan</th></tr>@forelse($audits as $a)<tr><td>{{$a->created_at}}</td><td>{{$a->actor}}</td><td>{{$a->action}}</td><td>{{$a->from_status}} → {{$a->to_status}}</td><td>{{$a->notes}}</td></tr>@empty<tr><td colspan="5">Belum ada audit.</td></tr>@endforelse</table></div></div></body></html>
